# =============================================================================
# models/db_schemes/project.py — Project Pydantic Schema
# =============================================================================
# PURPOSE:
#   Defines the data shape for a "project" document stored in MongoDB.
#   Pydantic validates all data going in and coming out of MongoDB.
#
# MongoDB collection: "projects"
# Document shape:
#   {
#     "_id":        ObjectId("64a3f..."),   ← auto-generated by MongoDB
#     "project_id": "demoproject"           ← URL-safe alphanumeric slug
#   }
#
# USED BY:
#   ProjectModel, routes/data.py, NlpController
#
# TEAM NOTE (Pair B — Member 4):
#   The project_id validator MUST enforce alphanumeric-only values because
#   it is used as a directory name AND a Qdrant collection name suffix.
#   Spaces or special characters would break the file system and Qdrant.
# =============================================================================

from pydantic import BaseModel, Field, validator
from bson import ObjectId
from typing import Optional


class Project(BaseModel):
    """
    Represents a single project document in the MongoDB "projects" collection.
    """

    id: Optional[str] = Field(None, alias="_id")
    project_id: str

    @validator("project_id")
    def project_id_must_be_alphanumeric(cls, v):
        """
        Ensures project_id contains only letters and digits.
        No spaces, hyphens, or special characters allowed.
        """
        if not v.isalnum():
            raise ValueError(
                f"project_id must be alphanumeric only. Got: '{v}'"
            )
        return v.lower()          # normalise to lowercase for consistency

    class Config:
        # Allows MongoDB ObjectId to be serialized as a string
        arbitrary_types_allowed = True
        json_encoders = {ObjectId: str}
        populate_by_name = True   # allows both "_id" and "id" field names
